/**
 * frontend/src/sw-register.js — Service Worker Registration & Offline Dead-Zone Queue Sync.
 *
 * 1. Registers the Workbox service worker generated by `vite-plugin-pwa` (`virtual:pwa-register`).
 * 2. Listens for `window.addEventListener('online')` to automatically flush any queued
 *    PWA Check-In / Check-Out attendance payloads recorded while the physician was in a
 *    hospital basement or shielded operating room with dead cellular reception.
 */

import { registerSW } from 'virtual:pwa-register';

const OFFLINE_TIMELOG_QUEUE_KEY = 'chronomed_offline_timelog_queue_v1';

export function initChronoMedPWA({ onOfflineReady, onNeedRefresh } = {}) {
  const updateSW = registerSW({
    immediate: true,
    onOfflineReady() {
      if (typeof onOfflineReady === 'function') onOfflineReady();
    },
    onNeedRefresh() {
      if (typeof onNeedRefresh === 'function') onNeedRefresh(updateSW);
    },
  });

  if (typeof window !== 'undefined') {
    window.addEventListener('online', () => {
      flushOfflineTimeLogQueue();
    });
  }

  return updateSW;
}

/**
 * Enqueues a Check-In or Check-Out request in localStorage when `navigator.onLine === false`
 * or when a network request fails inside a hospital dead zone.
 */
export function enqueueOfflineTimeLogAction(actionPayload) {
  try {
    const raw = localStorage.getItem(OFFLINE_TIMELOG_QUEUE_KEY);
    const queue = raw ? JSON.parse(raw) : [];
    queue.push({
      ...actionPayload,
      queuedAtTs: Math.floor(Date.now() / 1000),
    });
    localStorage.setItem(OFFLINE_TIMELOG_QUEUE_KEY, JSON.stringify(queue));
  } catch {
    // Ignore storage quota errors in restricted webviews
  }
}

/**
 * Replays queued Check-In / Check-Out mutations once cellular/Wi-Fi connectivity returns.
 */
export async function flushOfflineTimeLogQueue(apiBaseUrl = '/api/v1', authToken = null) {
  try {
    const raw = localStorage.getItem(OFFLINE_TIMELOG_QUEUE_KEY);
    if (!raw) return [];
    const queue = JSON.parse(raw);
    if (!Array.isArray(queue) || queue.length === 0) return [];

    const remaining = [];
    const synced = [];

    for (const item of queue) {
      try {
        const res = await fetch(`${apiBaseUrl}${item.endpoint}`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            ...(authToken ? { Authorization: `Bearer ${authToken}` } : {}),
          },
          body: JSON.stringify(item.body),
        });
        if (res.ok) {
          synced.push(item);
        } else {
          remaining.push(item);
        }
      } catch {
        remaining.push(item);
      }
    }

    localStorage.setItem(OFFLINE_TIMELOG_QUEUE_KEY, JSON.stringify(remaining));
    return synced;
  } catch {
    return [];
  }
}
